// ============================================
// PREPARE IMAGE REQUEST - gpt-image (azy.daily#383)
// ============================================
// DALL-E n'est plus servi par OpenAI (HTTP 400 « model does not exist », 14/09).
// La famille gpt-image refuse quality standard/hd, style et response_format.
// Le corps est construit ICI puis JSON.stringify : l'ancien JSON écrit en dur
// ("prompt": "{{ ... }}") cassait dès qu'un prompt contenait un guillemet.
// Toute valeur hors liste est refusée en 400 AVANT l'appel.

const input = $input.first().json;
const body = input.body || {};
const ctx = body.context || {};
const opts = body.options || {};
const errors = [];

// options.X prime sur X à la racine
const lire = nom => [opts[nom], body[nom]].find(v => v !== undefined && v !== null && v !== '');

// --- prompt (requis) ---
const prompt = body.prompt;
if (typeof prompt !== 'string' || prompt.trim().length === 0) {
  errors.push('prompt requis (chaîne non vide)');
}

// --- model : libre (catalogue), défaut gpt-image-1-mini ---
const modelDemande = lire('model');
let model = 'gpt-image-1-mini';
if (modelDemande !== undefined) {
  if (typeof modelDemande !== 'string' || modelDemande.trim().length === 0) {
    errors.push('model doit être une chaîne non vide');
  } else {
    model = modelDemande.trim();
  }
}

// --- n : 1 à 10, défaut 1 ---
const nDemande = lire('n');
let n = 1;
if (nDemande !== undefined) {
  n = Number(nDemande);
  if (!Number.isInteger(n) || n < 1 || n > 10) {
    errors.push('n doit être un entier entre 1 et 10');
  }
}

// --- size : anciennes tailles DALL-E converties ---
const TAILLES = ['1024x1024', '1536x1024', '1024x1536', 'auto'];
const ANCIENNES_TAILLES = { '1792x1024': '1536x1024', '1024x1792': '1024x1536' };
const sizeDemande = lire('size');
const size = sizeDemande === undefined ? '1024x1024' : (ANCIENNES_TAILLES[sizeDemande] || sizeDemande);
if (!TAILLES.includes(size)) {
  errors.push(`size invalide (${String(sizeDemande)}), valeurs acceptées ${TAILLES.join(' | ')}`);
}

// --- quality : anciennes qualités DALL-E converties ---
const QUALITES = ['low', 'medium', 'high', 'auto'];
const ANCIENNES_QUALITES = { standard: 'medium', hd: 'high' };
const qualityDemande = lire('quality');
const quality = qualityDemande === undefined ? 'auto' : (ANCIENNES_QUALITES[qualityDemande] || qualityDemande);
if (!QUALITES.includes(quality)) {
  errors.push(`quality invalide (${String(qualityDemande)}), valeurs acceptées ${QUALITES.join(' | ')}`);
}

// --- facultatifs : transmis seulement s'ils sont fournis ---
const FORMATS = ['png', 'jpeg', 'webp'];
const outputFormat = lire('output_format');
if (outputFormat !== undefined && !FORMATS.includes(outputFormat)) {
  errors.push(`output_format invalide (${String(outputFormat)}), valeurs acceptées ${FORMATS.join(' | ')}`);
}
const compressionDemandee = lire('output_compression');
const outputCompression = compressionDemandee === undefined ? undefined : Number(compressionDemandee);
if (outputCompression !== undefined && (!Number.isInteger(outputCompression) || outputCompression < 0 || outputCompression > 100)) {
  errors.push('output_compression doit être un entier entre 0 et 100');
}
const FONDS = ['transparent', 'opaque', 'auto'];
const background = lire('background');
if (background !== undefined && !FONDS.includes(background)) {
  errors.push(`background invalide (${String(background)}), valeurs acceptées ${FONDS.join(' | ')}`);
}

// --- clé OpenAI : BYOT, jamais de credential ni de variable d'environnement ---
// La clé ne sort de ce nœud que vers l'en-tête Authorization ; elle n'est
// jamais recopiée dans la réponse, le rappel ni les erreurs.
const cleFournie = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai;
const openaiApiKey = typeof cleFournie === 'string' ? cleFournie.trim() : '';
if (!openaiApiKey) {
  errors.push('openai_api_key requis (ou context.openai_api_key, plugin_context.api_keys.openai)');
}

const executionMode = body.execution_mode || 'online';
const callbackUrl = typeof body.callback_url === 'string' ? body.callback_url.trim() : '';

if (errors.length > 0) {
  return {
    valid: false,
    response: {
      success: false,
      error: {
        code: 400,
        http_status: 400,
        message: errors.join(' ; '),
        status: 'BAD_REQUEST',
        errors: errors
      },
      meta: { provider: 'openai', execution_mode: executionMode }
    }
  };
}

const imageBody = { model, prompt, n, size, quality };
if (outputFormat !== undefined) imageBody.output_format = outputFormat;
if (outputCompression !== undefined) imageBody.output_compression = outputCompression;
if (background !== undefined) imageBody.background = background;

return {
  valid: true,
  image_body: JSON.stringify(imageBody),
  openai_api_key: openaiApiKey,
  model: model,
  n: n,
  size: size,
  quality: quality,
  output_format: outputFormat || 'png',
  background: background || null,
  prompt: prompt,
  callback_url: callbackUrl,
  job_id: body.job_id || null,
  execution_mode: executionMode,
  startTime: Date.now()
};

// `crypto.randomUUID()` est indisponible : le bac a sable interdit require().
// `$execution.id` est unique par execution (n8n-workflows#476).
const nouvelId = () => 'job_' + $execution.id + '_' + Date.now().toString(36);
const webhookData = $input.first().json;

// Generate or use provided job_id
const job_id = webhookData.job_id || nouvelId();
const callback_url = webhookData.callback_url;

return [{
  json: {
    ...webhookData,
    job_context: {
      job_id: job_id,
      callback_url: callback_url,
      started_at: new Date().toISOString()
    }
  }
}];

// ============================================
// FORMAT OUTPUT (Async) - gpt-image (azy.daily#383)
// ============================================
// Contrat : data.images [{ b64_json, mime_type }] + usage du fournisseur TEL
// QUEL (facturation au jeton chez chat.api). Plus de table de prix : aucun
// prix n'est inventé ici.

const input = $input.first().json;
const req = $('Store Job Context').first().json;
const ASYNC = true;
const latencyMs = Date.now() - (req.startTime || Date.now());

// La clé BYOT ne doit JAMAIS ressortir. L'objet d'erreur du nœud HTTP peut
// embarquer la requête, en-têtes compris : il n'est jamais recopié tel quel,
// et toute occurrence de la clé est masquée dans la sortie finale.
const cle = String(req.openai_api_key || '');
const masquer = v => {
  if (typeof v === 'string') return cle.length >= 8 && v.includes(cle) ? v.split(cle).join('[clé masquée]') : v;
  if (Array.isArray(v)) return v.map(masquer);
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v)) o[k] = masquer(v[k]);
    return o;
  }
  return v;
};

const suivi = statut => ASYNC ? { job_id: req.job_context.job_id, status: statut } : {};
const meta = {
  provider: 'openai',
  model: req.model,
  execution_mode: req.execution_mode || 'online',
  latency_ms: latencyMs
};
const echec = (statut, message, type, codeFournisseur) => masquer({
  success: false,
  ...suivi('failed'),
  error: {
    code: statut,
    http_status: statut,
    message: message,
    status: type,
    provider_code: codeFournisseur
  },
  meta: meta,
  ...(ASYNC ? { job_context: req.job_context } : {})
});

if (input.error) {
  // Avec onError=continueRegularOutput, n8n n'émet pas statusCode : le statut
  // est enfoui dans le message sous la forme « 401 - {...} ». Sans statut
  // (panne réseau, délai dépassé) → 502.
  const brut = String(input.error.message || input.message || '');
  let statut = Number(input.statusCode ?? input.error.statusCode ?? input.error.status ?? input.error.httpCode);
  const m = brut.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/) || brut.match(/\b([45]\d{2})\s*-\s*([{\["][\s\S]*)$/);
  if (!(statut >= 400 && statut <= 599) && m) statut = parseInt(m[1], 10);
  if (!(statut >= 400 && statut <= 599)) statut = 502;

  let corpsAmont = null;
  if (m) {
    try {
      corpsAmont = JSON.parse(m[2]);
      if (typeof corpsAmont === 'string') corpsAmont = JSON.parse(corpsAmont);
    } catch (e) {
      corpsAmont = null;
    }
  }
  const erreurAmont = (corpsAmont && corpsAmont.error) || {};
  return echec(
    statut,
    erreurAmont.message || input.error.description || brut || 'OpenAI API error',
    erreurAmont.type || (m ? 'API_ERROR' : 'NETWORK_ERROR'),
    erreurAmont.code || input.error.code || null
  );
}

const formatSortie = input.output_format || req.output_format || 'png';
const MIME = { png: 'image/png', jpeg: 'image/jpeg', webp: 'image/webp' };
const images = (Array.isArray(input.data) ? input.data : [])
  .filter(img => img && typeof img.b64_json === 'string' && img.b64_json.length > 0)
  .map(img => ({ b64_json: img.b64_json, mime_type: MIME[formatSortie] || 'image/png' }));

if (images.length === 0) {
  return echec(502, 'Réponse OpenAI sans image (data[].b64_json absent)', 'EMPTY_RESPONSE', null);
}

return masquer({
  success: true,
  ...suivi('completed'),
  data: {
    images: images,
    model: input.model || req.model,
    size: input.size || req.size,
    quality: input.quality || req.quality,
    output_format: formatSortie,
    background: input.background || req.background || null,
    created: input.created || null
  },
  // usage dans meta.usage, comme le dispatch et Text Generator : chat.api n'a qu'un
  // endroit à lire pour facturer (au jeton ici). Tel qu'OpenAI le renvoie.
  meta: { ...meta, usage: input.usage || null },
  ...(ASYNC ? { job_context: req.job_context } : {})
});

// Signature deleguee au noeud Crypto natif qui suit : le bac a sable n8n
// interdit require('crypto'). Cf. n8n-workflows#476.
const item = $input.first().json;

// Extract callback URL from job context
const callback_url = item.job_context.callback_url;

// Prepare the callback body (without job_context internal data)
const callbackBody = {
  success: item.success,
  job_id: item.job_id,
  status: item.status,
  data: item.data,
  meta: item.meta
};

if (item.error) {
  callbackBody.error = item.error;
}

// Generate HMAC signature (RFC-040 format)
const corps_json = JSON.stringify(callbackBody);

return [{
  json: {
    callback_url: callback_url,
    callback_body: callbackBody,
    corps_json: corps_json,
    rappel_signable: !!$env.N8N_WEBHOOK_SECRET
  }
}];

