const items = $input.all();
const jobContextData = $('Store Job Context').first().json;
const webhookData = jobContextData;

const PRICING = {
  'dall-e-3': {
    'standard': { '1024x1024': 0.04, '1792x1024': 0.08, '1024x1792': 0.08 },
    'hd': { '1024x1024': 0.08, '1792x1024': 0.12, '1024x1792': 0.12 }
  },
  'dall-e-2': {
    'standard': { '256x256': 0.016, '512x512': 0.018, '1024x1024': 0.02 }
  }
};

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        job_id: jobContextData.job_context.job_id,
        status: 'failed',
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'Unknown error',
          status: item.json.error.type || 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: webhookData.body.execution_mode || 'online'
        },
        job_context: jobContextData.job_context
      }
    };
  }

  const model = webhookData.body.options?.model || 'dall-e-3';
  const quality = webhookData.body.options?.quality || 'standard';
  const size = webhookData.body.options?.size || '1024x1024';
  const n = webhookData.body.options?.n || 1;

  const unitPrice = PRICING[model]?.[quality]?.[size] || 0.04;
  const costEstimate = unitPrice * n;

  const images = (item.json.data || []).map(img => ({
    url: img.url || null,
    b64_json: img.b64_json || null,
    revised_prompt: img.revised_prompt || null,
    size: size
  }));

  return {
    json: {
      success: true,
      job_id: jobContextData.job_context.job_id,
      status: 'completed',
      data: {
        images: images,
        prompt_original: webhookData.body.prompt,
        prompt_revised: images[0]?.revised_prompt || null
      },
      meta: {
        provider: 'openai',
        model: model,
        execution_mode: webhookData.body.execution_mode || 'online',
        cost_estimate_usd: costEstimate
